  "content": "import numpy as np, gauge

def alt_profile(f, ri=14, ro=30):
    img=gauge.DIFF[f]; cx,cy=gauge.CENTERS['alt']
    rs=np.arange(ri,ro); out=np.zeros(360)
    for i in range(360):
        t=np.deg2rad(i); xs=(cx+rs*np.sin(t)).astype(int); ys=(cy-rs*np.cos(t)).astype(int)
        out[i]=img[ys,xs].mean()
    return gauge.smooth(out,3)

def find_peaks(p, minprom=6):
    peaks=[]
    for i in range(360):
        v=p[i]
        if v>=p[(i-1)%360] and v>=p[(i+1)%360] and v>minprom:
            peaks.append(i)
    # merge adjacent
    merged=[]
    for i in peaks:
        if merged and min((i-merged[-1])%360,(merged[-1]-i)%360)<=3:
            if p[i]>p[merged[-1]]: merged[-1]=i
        else: merged.append(i)
    return merged

def peak_width(p, c):
    half=p[c]*0.5
    l=0
    while l<180 and p[(c-l)%360]>half: l+=1
    r=0
    while r<180 and p[(c+r)%360]>half: r+=1
    return l+r

if __name__=='__main__':
    for lbl,f in {'4000@180':180,'4400@380':380,'4800@600':600,'4800@680':680}.items():
        p=alt_profile(f)
        pk=find_peaks(p, p.max()*0.35)
        info=[(c,round(float(p[c]),1),peak_width(p,c)) for c in pk]
        print(lbl,'peaks(ang,val,width):',info)
